    pattern_rows = [r for r, row in enumerate(input_grid) if 0 in row and 8 in row]
    cols_with_8 = set()
    cols_with_0 = set()

    for r in pattern_rows:
        for c, v in enumerate(input_grid[r]):
            if v == 8:
                cols_with_8.add(c)
            else:
                cols_with_0.add(c)

    row_descriptions = []
    for r, row in enumerate(input_grid):
        output_row = []
        for c in range(len(input_grid[0])):
            if c == ref_col:
                output_row.append(2)
            elif c in cols_with_8:
